def mp_inverse(a, rcond=1e-12):
    u, s, vt = np.linalg.svd(a, full_matrices=False)
    cutoff = rcond * s[0]

    s_inv = np.zeros_like(s)
    for i, val in enumerate(s):
        if val > cutoff:
            s_inv[i] = 1.0 / val

    return vt.T @ np.diag(s_inv) @ u.T

